Pixel parse_color(const char * str)
{
	Pixel col;
	if(std::sscanf(str, "%02hhx%02hhx%02hhx", &col(0), &col(1), &col(2)) < 3)
		serror("Error parsing colorization color in '%s'!", str);
	return col;
}

